const body = $json.body ?? $json;

const action = String(body.action ?? '')
  .trim()
  .toLowerCase();

const usuario_id = body.usuario_id
  ? String(body.usuario_id).trim()
  : null;

const nombre = body.nombre
  ? String(body.nombre).trim()
  : null;

const email_normalizado = body.email
  ? String(body.email).trim().toLowerCase()
  : body.email_normalizado
    ? String(body.email_normalizado).trim().toLowerCase()
    : null;

const password =
  typeof body.password === 'string'
    ? body.password
    : null;

const accionesPermitidas = [
  'create',
  'profile',
  'update',
  'deactivate',
];

let error = null;

if (!accionesPermitidas.includes(action)) {
  error = 'Acción no válida';
}

if (!error && action === 'create') {
  if (!nombre) {
    error = 'El nombre es obligatorio';
  } else if (!email_normalizado) {
    error = 'El email es obligatorio';
  } else if (!password) {
    error = 'La contraseña es obligatoria';
  }
}

if (!error && action === 'profile') {
  if (!usuario_id) {
    error = 'usuario_id es obligatorio';
  }
}

if (!error && action === 'update') {
  if (!usuario_id) {
    error = 'usuario_id es obligatorio';
  } else if (!nombre && !email_normalizado) {
    error = 'Debe enviarse al menos un dato para actualizar';
  }
}

if (!error && action === 'deactivate') {
  if (!usuario_id) {
    error = 'usuario_id es obligatorio';
  }
}

return [
  {
    json: {
      route: error ? 'invalid' : action,
      action,
      usuario_id,
      nombre,
      email_normalizado,
      password,
      error,
    },
  },
];

const crypto = require('crypto');

const input = $('Normalizar y validar entrada').item.json;

const usuario_id = `usr_${crypto.randomUUID()}`;

const password_salt = crypto.randomBytes(16).toString('hex');

const password_hash = crypto
  .pbkdf2Sync(
    input.password,
    password_salt,
    100000,
    32,
    'sha256'
  )
  .toString('hex');

const ahora = new Date().toISOString();

return [
  {
    json: {
      usuario_id,
      nombre: input.nombre,
      email_normalizado: input.email_normalizado,
      password_hash,
      password_salt,
      estado: 'ACTIVO',
      fecha_registro: ahora,
      fecha_actualizacion: ahora,
    },
  },
];

