const actual = $json;
const entrada = $('Normalizar y validar entrada').first().json;

const emailNuevo =
  entrada.email_normalizado || actual.email_normalizado;

const nombreNuevo =
  entrada.nombre || actual.nombre;

return [
  {
    json: {
      usuario_id: actual.usuario_id,

      nombre_actual: actual.nombre,
      email_actual: actual.email_normalizado,

      nombre_nuevo: nombreNuevo,
      email_nuevo: emailNuevo,

      email_cambia:
        emailNuevo !== actual.email_normalizado,

      password_hash: actual.password_hash,
      password_salt: actual.password_salt,
      estado: actual.estado,
      fecha_registro: actual.fecha_registro,

      fecha_actualizacion: new Date().toISOString()
    }
  }
];

const crypto = require('crypto');

const actualizado = $('Actualizar usuario').first().json;
const datos = $('Preparar actualización').first().json;

const cambios = [];

if (datos.nombre_actual !== datos.nombre_nuevo) {
  cambios.push(`nombre: "${datos.nombre_actual}" → "${datos.nombre_nuevo}"`);
}

if (datos.email_actual !== datos.email_nuevo) {
  cambios.push(`email: "${datos.email_actual}" → "${datos.email_nuevo}"`);
}

return [
  {
    json: {
      auditoria_id: `aud_${crypto.randomUUID()}`,
      usuario_id: actualizado.usuario_id,
      accion: 'UPDATE',
      fecha: new Date().toISOString(),
      resultado: 'OK',
      detalle: cambios.length
        ? `Usuario actualizado. ${cambios.join(' | ')}`
        : 'Usuario actualizado sin cambios relevantes',
    },
  },
];

